INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'bd16d4df3136', '我向你们教授超人。人是一种应当被超越的东西。为了超越人，你们做过什么？', 'I teach you the Superman. Man is something that is to be surpassed. What have ye done to surpass man?', '尼采', '《查拉图斯特拉如是说》·序言 3', 'book', '["超越","自我"]', 'public', '', 1792512063000, 1792512063000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '我向你们教授超人。人是一种应当被超越的东西。为了超越人，你们做过什么？' OR id = 'bd16d4df3136');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '909316387dab', '人是一根绳索，系在野兽与超人之间——一根悬在深渊之上的绳索。人之伟大，在于他是一座桥梁，而不是终点。', 'Man is a rope stretched between the animal and the Superman—a rope over an abyss. … What is great in man is that he is a bridge and not a goal.', '尼采', '《查拉图斯特拉如是说》·序言 4', 'book', '["超越","深渊"]', 'public', '', 1792512062000, 1792512062000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '人是一根绳索，系在野兽与超人之间——一根悬在深渊之上的绳索。人之伟大，在于他是一座桥梁，而不是终点。' OR id = '909316387dab');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '105581d9169e', '我告诉你们：人的心中必须还留有混沌，才能孕育出一颗舞动的星辰。', 'I tell you: one must still have chaos in one, to give birth to a dancing star.', '尼采', '《查拉图斯特拉如是说》·序言 5', 'book', '["创造","自我"]', 'public', '', 1792512061000, 1792512061000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '我告诉你们：人的心中必须还留有混沌，才能孕育出一颗舞动的星辰。' OR id = '105581d9169e');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '76908f5bbb2b', '一切文字之中，我只爱那用血写成的。用血去写吧，你会懂得：血就是精神。', 'Of all that is written, I love only what a person hath written with his blood. Write with blood, and thou wilt find that blood is spirit.', '尼采', '《查拉图斯特拉如是说》·第一部·读与写', 'book', '["写作","真诚"]', 'public', '', 1792512060000, 1792512060000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '一切文字之中，我只爱那用血写成的。用血去写吧，你会懂得：血就是精神。' OR id = '76908f5bbb2b');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'd3bf03c6f1fe', '我们热爱生命，不是因为习惯了活着，而是因为习惯了爱。爱里总有几分疯狂；而疯狂里，也总有几分章法。', 'It is true we love life; not because we are wont to live, but because we are wont to love. There is always some madness in love. But there is always, also, some method in madness.', '尼采', '《查拉图斯特拉如是说》·第一部·读与写', 'book', '["爱","生命"]', 'public', '', 1792512059000, 1792512059000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '我们热爱生命，不是因为习惯了活着，而是因为习惯了爱。爱里总有几分疯狂；而疯狂里，也总有几分章法。' OR id = 'd3bf03c6f1fe');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '490f79cf6fe8', '我只会相信一位懂得跳舞的神。', 'I should only believe in a God that would know how to dance.', '尼采', '《查拉图斯特拉如是说》·第一部·读与写', 'book', '["信仰","轻盈"]', 'public', '', 1792512058000, 1792512058000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '我只会相信一位懂得跳舞的神。' OR id = '490f79cf6fe8');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '42841c1ad93c', '攀上最高峰的人，会笑看一切悲剧——无论是戏台上的，还是现实里的。', 'He who climbeth on the highest mountains, laugheth at all tragic plays and tragic realities.', '尼采', '《查拉图斯特拉如是说》·第一部·读与写', 'book', '["高处","豁达"]', 'public', '', 1792512057000, 1792512057000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '攀上最高峰的人，会笑看一切悲剧——无论是戏台上的，还是现实里的。' OR id = '42841c1ad93c');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'b84430d5c58b', '你的身体里，藏着比你最高明的智慧更多的明智。', 'There is more sagacity in thy body than in thy best wisdom.', '尼采', '《查拉图斯特拉如是说》·第一部·身体的蔑视者', 'book', '["身体","智慧"]', 'public', '', 1792512056000, 1792512056000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '你的身体里，藏着比你最高明的智慧更多的明智。' OR id = 'b84430d5c58b');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '3a68f9175bce', '人和树是一样的。越是想向高处、向光明生长，他的根就越是用力地扎向大地，扎向下方，扎进黑暗与深处——扎进恶。', 'But it is the same with man as with the tree. The more he seeketh to rise into the height and light, the more vigorously do his roots struggle earthward, downward, into the dark and deep—into the evil.', '尼采', '《查拉图斯特拉如是说》·第一部·山上的树', 'book', '["成长","黑暗"]', 'public', '', 1792512055000, 1792512055000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '人和树是一样的。越是想向高处、向光明生长，他的根就越是用力地扎向大地，扎向下方，扎进黑暗与深处——扎进恶。' OR id = '3a68f9175bce');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'b4818cf9e763', '逃吧，我的朋友，逃进你的孤独里去！我看见你被大人物的喧嚣震聋了耳朵，又被小人物的毒刺蜇得遍体是伤。', 'Flee, my friend, into thy solitude! I see thee deafened with the noise of the great men, and stung all over with the stings of the little ones.', '尼采', '《查拉图斯特拉如是说》·第一部·市场的苍蝇', 'book', '["孤独"]', 'public', '', 1792512054000, 1792512054000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '逃吧，我的朋友，逃进你的孤独里去！我看见你被大人物的喧嚣震聋了耳朵，又被小人物的毒刺蜇得遍体是伤。' OR id = 'b4818cf9e763');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'ce5255846a1f', '一切伟大的事物，都发生在远离市场、远离名声的地方。', 'Away from the market-place and from fame taketh place all that is great.', '尼采', '《查拉图斯特拉如是说》·第一部·市场的苍蝇', 'book', '["孤独","伟大"]', 'public', '', 1792512053000, 1792512053000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '一切伟大的事物，都发生在远离市场、远离名声的地方。' OR id = 'ce5255846a1f');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '91e850e8b308', '你必须甘愿在自己的火焰中焚烧：若不先化为灰烬，你又怎能焕然一新！', 'Ready must thou be to burn thyself in thine own flame; how couldst thou become new if thou have not first become ashes!', '尼采', '《查拉图斯特拉如是说》·第一部·创造者之路', 'book', '["重生","自我"]', 'public', '', 1792512052000, 1792512052000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '你必须甘愿在自己的火焰中焚烧：若不先化为灰烬，你又怎能焕然一新！' OR id = '91e850e8b308');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '05fab1d0d7d1', '勇气是最好的杀手，是主动出击的勇气：它甚至能杀死死亡本身，因为它说：“这就是生命吗？好！那就再来一次！”', 'Courage, however, is the best slayer, courage which attacketh: it slayeth even death itself; for it saith: “Was that life? Well! Once more!”', '尼采', '《查拉图斯特拉如是说》·第三部·幻影与谜', 'book', '["勇气","生命"]', 'public', '', 1792512051000, 1792512051000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '勇气是最好的杀手，是主动出击的勇气：它甚至能杀死死亡本身，因为它说：“这就是生命吗？好！那就再来一次！”' OR id = '05fab1d0d7d1');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'dae86269a22c', '人必须学会爱自己——我如此教导——用一种完好而健康的爱：好让人能忍受与自己相处，而不必四处游荡。', 'One must learn to love oneself—thus do I teach—with a wholesome and healthy love: that one may endure to be with oneself, and not go roving about.', '尼采', '《查拉图斯特拉如是说》·第三部·重力之魔', 'book', '["自爱","自我"]', 'public', '', 1792512050000, 1792512050000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '人必须学会爱自己——我如此教导——用一种完好而健康的爱：好让人能忍受与自己相处，而不必四处游荡。' OR id = 'dae86269a22c');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'ab6785cf42d2', '“这——就是我的路。你的路在哪里？”每当有人向我打听“那条路”，我便这样回答。因为“那条路”——根本不存在！', '“This—is now my way,—where is yours?” Thus did I answer those who asked me “the way.” For the way—it doth not exist!', '尼采', '《查拉图斯特拉如是说》·第三部·重力之魔', 'book', '["道路","自我"]', 'public', '', 1792512049000, 1792512049000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '“这——就是我的路。你的路在哪里？”每当有人向我打听“那条路”，我便这样回答。因为“那条路”——根本不存在！' OR id = 'ab6785cf42d2');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '312cd3affd7a', '与怪物搏斗的人，要当心自己不因此也成为怪物。当你久久凝视深渊，深渊也在凝视着你。', 'He who fights with monsters should be careful lest he thereby become a monster. And if thou gaze long into an abyss, the abyss will also gaze into thee.', '尼采', '《善恶的彼岸》§146', 'book', '["深渊","自省"]', 'public', '', 1792512048000, 1792512048000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '与怪物搏斗的人，要当心自己不因此也成为怪物。当你久久凝视深渊，深渊也在凝视着你。' OR id = '312cd3affd7a');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'cac50f84a49a', '出于爱而做的事，总是发生在善恶的彼岸。', 'What is done out of love always takes place beyond good and evil.', '尼采', '《善恶的彼岸》§153', 'book', '["爱"]', 'public', '', 1792512047000, 1792512047000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '出于爱而做的事，总是发生在善恶的彼岸。' OR id = 'cac50f84a49a');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'ced44a4ff9fe', '人的成熟，意味着重新找回儿时游戏时的那份认真。', 'The maturity of man—that means, to have reacquired the seriousness that one had as a child at play.', '尼采', '《善恶的彼岸》§94', 'book', '["成长","童心"]', 'public', '', 1792512046000, 1792512046000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '人的成熟，意味着重新找回儿时游戏时的那份认真。' OR id = 'ced44a4ff9fe');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '7aebf5d17340', '作为天文学家的智者——只要你仍觉得群星在你“之上”，你就还缺一双洞察者的眼睛。', 'THE SAGE AS ASTRONOMER.—So long as thou feelest the stars as an “above thee,” thou lackest the eye of the discerning one.', '尼采', '《善恶的彼岸》§71', 'book', '["星辰","视野"]', 'public', '', 1792512045000, 1792512045000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '作为天文学家的智者——只要你仍觉得群星在你“之上”，你就还缺一双洞察者的眼睛。' OR id = '7aebf5d17340');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'ab183051cc4f', '每一个深邃的灵魂都需要一副面具；不仅如此，在每一个深邃的灵魂周围，都有一副面具在不断生长。', 'Every profound spirit needs a mask; nay, more, around every profound spirit there continually grows a mask.', '尼采', '《善恶的彼岸》§40', 'book', '["深刻","孤独"]', 'public', '', 1792512044000, 1792512044000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '每一个深邃的灵魂都需要一副面具；不仅如此，在每一个深邃的灵魂周围，都有一副面具在不断生长。' OR id = 'ab183051cc4f');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'e2330331482d', '“这是我做的，”我的记忆说。“我不可能做出那种事，”我的骄傲说，而且寸步不让。最后——记忆让步了。', '“I did that,” says my memory. “I could not have done that,” says my pride, and remains inexorable. Eventually—the memory yields.', '尼采', '《善恶的彼岸》§68', 'book', '["记忆","骄傲"]', 'public', '', 1792512043000, 1792512043000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '“这是我做的，”我的记忆说。“我不可能做出那种事，”我的骄傲说，而且寸步不让。最后——记忆让步了。' OR id = 'e2330331482d');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '89ce5e8df0e3', '人应当像奥德修斯告别瑙西卡那样告别生命——心怀祝福，而非恋恋不舍。', 'One should part from life as Ulysses parted from Nausicaa—blessing it rather than in love with it.', '尼采', '《善恶的彼岸》§96', 'book', '["生命","告别"]', 'public', '', 1792512042000, 1792512042000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '人应当像奥德修斯告别瑙西卡那样告别生命——心怀祝福，而非恋恋不舍。' OR id = '89ce5e8df0e3');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'ee2e1f4e5f3b', '反驳、闪避、愉快的怀疑与对反讽的偏爱，都是健康的迹象；一切绝对之物，都属于病理学。', 'Objection, evasion, joyous distrust, and love of irony are signs of health; everything absolute belongs to pathology.', '尼采', '《善恶的彼岸》§154', 'book', '["怀疑","健康"]', 'public', '', 1792512041000, 1792512041000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '反驳、闪避、愉快的怀疑与对反讽的偏爱，都是健康的迹象；一切绝对之物，都属于病理学。' OR id = 'ee2e1f4e5f3b');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '7934c8fbb121', '上帝死了！上帝一直死着！是我们杀死了他！我们这些凶手中的凶手，该如何安慰自己？', 'God is dead! God remains dead! And we have killed him! How shall we console ourselves, the most murderous of all murderers?', '尼采', '《快乐的科学》§125', 'book', '["信仰","虚无"]', 'public', '', 1792512040000, 1792512040000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '上帝死了！上帝一直死着！是我们杀死了他！我们这些凶手中的凶手，该如何安慰自己？' OR id = '7934c8fbb121');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'ead6c467b511', '道德，是个体身上的群体本能。', 'Morality is the herd-instinct in the individual.', '尼采', '《快乐的科学》§116', 'book', '["道德","群体"]', 'public', '', 1792512039000, 1792512039000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '道德，是个体身上的群体本能。' OR id = 'ead6c467b511');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'bfa8c152e068', '你的良心在说什么？——“你要成为你自己。”', 'What Saith thy Conscience?—“Thou shalt become what thou art.”', '尼采', '《快乐的科学》§270', 'book', '["自我"]', 'public', '', 1792512038000, 1792512038000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '你的良心在说什么？——“你要成为你自己。”' OR id = 'bfa8c152e068');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'baad5293fee4', '我愿越来越多地把事物中必然的部分视为美——如此，我便成了让万物变美的人之一。热爱命运：从今往后，就让这成为我的爱吧！', 'I want more and more to perceive the necessary characters in things as the beautiful:—I shall thus be one of those who beautify things. Amor fati: let that henceforth be my love!', '尼采', '《快乐的科学》§276', 'book', '["命运","爱"]', 'public', '', 1792512037000, 1792512037000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '我愿越来越多地把事物中必然的部分视为美——如此，我便成了让万物变美的人之一。热爱命运：从今往后，就让这成为我的爱吧！' OR id = 'baad5293fee4');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '2cf2111d795a', '相信我！——从生命中收获最丰硕的果实、最大的享受，秘诀就是：危险地生活！把你们的城市建在维苏威火山的山坡上！把你们的船驶向未经探索的海洋！', 'For believe me!—the secret of realising the largest productivity and the greatest enjoyment of existence is to live in danger! Build your cities on the slope of Vesuvius! Send your ships into unexplored seas!', '尼采', '《快乐的科学》§283', 'book', '["冒险","勇气"]', 'public', '', 1792512036000, 1792512036000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '相信我！——从生命中收获最丰硕的果实、最大的享受，秘诀就是：危险地生活！把你们的城市建在维苏威火山的山坡上！把你们的船驶向未经探索的海洋！' OR id = '2cf2111d795a');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'ee6ee8f98532', '我们要做自己生活的诗人，而且首先从最微小、最平凡的事情做起。', 'We, however, want to be the poets of our life, and first of all in the smallest and most commonplace matters.', '尼采', '《快乐的科学》§299', 'book', '["生活","诗意"]', 'public', '', 1792512035000, 1792512035000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '我们要做自己生活的诗人，而且首先从最微小、最平凡的事情做起。' OR id = 'ee6ee8f98532');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '0cead4ba2269', '倘若某个白天或夜里，一个恶魔悄悄尾随你，潜入你最孤寂的孤独，对你说：“你现在所过、过去所过的这种生活，你必须再过一次，还要再过无数次；其中不会有任何新东西，每一种痛苦、每一种欢乐、每一个念头、每一声叹息，都必将重新回到你身边。”', 'What if a demon crept after thee into thy loneliest loneliness some day or night, and said to thee: “This life, as thou livest it at present, and hast lived it, thou must live it once more, and also innumerable times; and there will be nothing new in it, but every pain and every joy and every thought and every sigh … must come to thee again.”', '尼采', '《快乐的科学》§341', 'book', '["命运","时间"]', 'public', '', 1792512034000, 1792512034000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '倘若某个白天或夜里，一个恶魔悄悄尾随你，潜入你最孤寂的孤独，对你说：“你现在所过、过去所过的这种生活，你必须再过一次，还要再过无数次；其中不会有任何新东西，每一种痛苦、每一种欢乐、每一个念头、每一声叹息，都必将重新回到你身边。”' OR id = '0cead4ba2269');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '653fe7756231', '什么造就英雄？——同时直面自己最深的痛苦与最高的希望。', 'What makes Heroic?—To face simultaneously one’s greatest suffering and one’s highest hope.', '尼采', '《快乐的科学》§268', 'book', '["勇气","希望"]', 'public', '', 1792512033000, 1792512033000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '什么造就英雄？——同时直面自己最深的痛苦与最高的希望。' OR id = '653fe7756231');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'be7f4233921b', '获得自由的印记是什么？——不再为自己感到羞耻。', 'What is the Seal of Liberty Attained?—To be no longer ashamed of oneself.', '尼采', '《快乐的科学》§275', 'book', '["自由","自我"]', 'public', '', 1792512032000, 1792512032000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '获得自由的印记是什么？——不再为自己感到羞耻。' OR id = 'be7f4233921b');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '7fd83768485a', '出自生活的军事学校：凡杀不死我的，都使我更强大。', 'From the military school of life.—That which does not kill me, makes me stronger.', '尼采', '《偶像的黄昏》·箴言与箭 8', 'book', '["坚韧"]', 'public', '', 1792512031000, 1792512031000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '出自生活的军事学校：凡杀不死我的，都使我更强大。' OR id = '7fd83768485a');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'e7f7b6837fbe', '一个人若知道自己为何而活，至于怎样活，便自会有着落。', 'If a man knows the wherefore of his existence, then the manner of it can take care of itself.', '尼采', '《偶像的黄昏》·箴言与箭 12', 'book', '["意义","坚韧"]', 'public', '', 1792512030000, 1792512030000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '一个人若知道自己为何而活，至于怎样活，便自会有着落。' OR id = 'e7f7b6837fbe');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'f3909e2014c6', '幸福所需的，是何等微小的东西！一支风笛的声音。没有音乐，生命将是一个错误。', 'What trifles constitute happiness! The sound of a bagpipe. Without music life would be a mistake.', '尼采', '《偶像的黄昏》·箴言与箭 33', 'book', '["音乐","幸福"]', 'public', '', 1792512029000, 1792512029000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '幸福所需的，是何等微小的东西！一支风笛的声音。没有音乐，生命将是一个错误。' OR id = 'f3909e2014c6');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '613546f6fe14', '久坐不动，才是对圣灵真正的冒犯。唯有在行走中得来的思想，才有价值。', 'A sedentary life is the real sin against the Holy Spirit. Only those thoughts that come by walking have any value.', '尼采', '《偶像的黄昏》·箴言与箭 34', 'book', '["行走","思考"]', 'public', '', 1792512028000, 1792512028000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '久坐不动，才是对圣灵真正的冒犯。唯有在行走中得来的思想，才有价值。' OR id = '613546f6fe14');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'c9680768f220', '有许多事物，我决意永远不去看见。——智慧，甚至为知识划定界限。', 'Once for all I wish to be blind to many things.—Wisdom sets bounds even to knowledge.', '尼采', '《偶像的黄昏》·箴言与箭 5', 'book', '["智慧"]', 'public', '', 1792512027000, 1792512027000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '有许多事物，我决意永远不去看见。——智慧，甚至为知识划定界限。' OR id = 'c9680768f220');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '409deabc48c6', '感官的精神化，就叫作爱。', 'The spiritualisation of sensuality is called love.', '尼采', '《偶像的黄昏》·作为反自然的道德 3', 'book', '["爱"]', 'public', '', 1792512026000, 1792512026000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '感官的精神化，就叫作爱。' OR id = '409deabc48c6');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '47cce808c4ab', '我的抱负，是用十句话说出别人用一整本书才说出的东西——说出别人用一整本书也说不出的东西。', 'It is my ambition to say in ten sentences what everyone else says in a whole book,—what everyone else does not say in a whole book.', '尼采', '《偶像的黄昏》·一个不合时宜者的漫游 51', 'book', '["写作"]', 'public', '', 1792512025000, 1792512025000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '我的抱负，是用十句话说出别人用一整本书才说出的东西——说出别人用一整本书也说不出的东西。' OR id = '47cce808c4ab');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '86370ba78383', '我衡量人之伟大的公式是“热爱命运”：不愿任何事物有所不同——无论在前方、在身后，还是在永恒之中。必然之事不仅要承受……更要去爱。', 'My formula for greatness in man is amor fati: the fact that a man wishes nothing to be different, either in front of him or behind him, or for all eternity. Not only must the necessary be borne … but it must also be loved.', '尼采', '《瞧，这个人》·我为什么这么聪明 10', 'book', '["命运","爱"]', 'public', '', 1792512024000, 1792512024000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '我衡量人之伟大的公式是“热爱命运”：不愿任何事物有所不同——无论在前方、在身后，还是在永恒之中。必然之事不仅要承受……更要去爱。' OR id = '86370ba78383');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'af15854cfab6', '唯有作为审美现象，存在与世界才永远是正当的。', 'For only as an æsthetic phenomenon is existence and the world eternally justified.', '尼采', '《悲剧的诞生》§5', 'book', '["艺术","存在"]', 'public', '', 1792512023000, 1792512023000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '唯有作为审美现象，存在与世界才永远是正当的。' OR id = 'af15854cfab6');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'b1d2ee72b64f', '古往今来，人类都分为奴隶与自由人两种：一天之中若没有三分之二的时间属于自己，那他就是奴隶，无论他是政治家、商人、官员还是学者。', 'All mankind is divided, as it was at all times and is still, into slaves and freemen; for whoever has not two-thirds of his day for himself is a slave, be he otherwise whatever he likes, statesman, merchant, official, or scholar.', '尼采', '《人性的，太人性的》§283', 'book', '["自由","时间"]', 'public', '', 1792512022000, 1792512022000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '古往今来，人类都分为奴隶与自由人两种：一天之中若没有三分之二的时间属于自己，那他就是奴隶，无论他是政治家、商人、官员还是学者。' OR id = 'b1d2ee72b64f');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '8db790ddf27e', '在我年纪尚轻、心思也更易受伤的那些年里，父亲给过我一句忠告，此后我一直在心里反复咀嚼。“每当你想批评别人的时候，”他对我说，“要记住，这世上并不是人人都拥有你所拥有的那些条件。”', 'In my younger and more vulnerable years my father gave me some advice that I’ve been turning over in my mind ever since. “Whenever you feel like criticizing anyone,” he told me, “just remember that all the people in this world haven’t had the advantages that you’ve had.”', '菲茨杰拉德', '《了不起的盖茨比》第一章', 'book', '["宽容"]', 'public', '', 1792512021000, 1792512021000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '在我年纪尚轻、心思也更易受伤的那些年里，父亲给过我一句忠告，此后我一直在心里反复咀嚼。“每当你想批评别人的时候，”他对我说，“要记住，这世上并不是人人都拥有你所拥有的那些条件。”' OR id = '8db790ddf27e');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '50da7e2fbff4', '不轻下评判，意味着怀抱无尽的希望。', 'Reserving judgements is a matter of infinite hope.', '菲茨杰拉德', '《了不起的盖茨比》第一章', 'book', '["希望","宽容"]', 'public', '', 1792512020000, 1792512020000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '不轻下评判，意味着怀抱无尽的希望。' OR id = '50da7e2fbff4');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '3c63c91d1f22', '“我希望她是个傻瓜——在这世上，一个女孩最好的样子，就是做个美丽的小傻瓜。”', '“I hope she’ll be a fool—that’s the best thing a girl can be in this world, a beautiful little fool.”', '菲茨杰拉德', '《了不起的盖茨比》第一章', 'book', '["无奈"]', 'public', '', 1792512019000, 1792512019000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '“我希望她是个傻瓜——在这世上，一个女孩最好的样子，就是做个美丽的小傻瓜。”' OR id = '3c63c91d1f22');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '4e3690cd06a8', '他以一种奇特的姿势朝漆黑的海水伸出双臂；虽然离他很远，我也敢发誓他在颤抖。我不由自主地望向海面——什么也看不清，只有一盏绿灯，微小而遥远，也许是某个码头的尽头。', 'He stretched out his arms toward the dark water in a curious way, and, far as I was from him, I could have sworn he was trembling. Involuntarily I glanced seaward—and distinguished nothing except a single green light, minute and far away, that might have been the end of a dock.', '菲茨杰拉德', '《了不起的盖茨比》第一章', 'book', '["梦想","渴望"]', 'public', '', 1792512018000, 1792512018000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '他以一种奇特的姿势朝漆黑的海水伸出双臂；虽然离他很远，我也敢发誓他在颤抖。我不由自主地望向海面——什么也看不清，只有一盏绿灯，微小而遥远，也许是某个码头的尽头。' OR id = '4e3690cd06a8');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '59d4f73316a1', '我身在其中，又置身其外；既为生活无穷无尽的千姿百态而着迷，又对它心生厌倦。', 'I was within and without, simultaneously enchanted and repelled by the inexhaustible variety of life.', '菲茨杰拉德', '《了不起的盖茨比》第二章', 'book', '["生活"]', 'public', '', 1792512017000, 1792512017000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '我身在其中，又置身其外；既为生活无穷无尽的千姿百态而着迷，又对它心生厌倦。' OR id = '59d4f73316a1');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '9b67f0c792ce', '他会意地一笑——远不止是会意。那是一种罕见的微笑，带着永恒的、令人安心的力量，一生中或许只能遇见四五回。……它理解你，恰好到你希望被理解的程度；它相信你，正如你希望相信自己那样；它让你确信，它对你的印象，正是你在最好的时候想要留给别人的那个印象。', 'He smiled understandingly—much more than understandingly. It was one of those rare smiles with a quality of eternal reassurance in it, that you may come across four or five times in life. … It understood you just so far as you wanted to be understood, believed in you as you would like to believe in yourself, and assured you that it had precisely the impression of you that, at your best, you hoped to convey.', '菲茨杰拉德', '《了不起的盖茨比》第三章', 'book', '["相遇","温柔"]', 'public', '', 1792512016000, 1792512016000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '他会意地一笑——远不止是会意。那是一种罕见的微笑，带着永恒的、令人安心的力量，一生中或许只能遇见四五回。……它理解你，恰好到你希望被理解的程度；它相信你，正如你希望相信自己那样；它让你确信，它对你的印象，正是你在最好的时候想要留给别人的那个印象。' OR id = '9b67f0c792ce');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'df9eb910b7bb', '“而且我喜欢热闹的大派对，那样多亲密。小聚会上反倒一点私密都没有。”', '“And I like large parties. They’re so intimate. At small parties there isn’t any privacy.”', '菲茨杰拉德', '《了不起的盖茨比》第三章', 'book', '["人群"]', 'public', '', 1792512015000, 1792512015000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '“而且我喜欢热闹的大派对，那样多亲密。小聚会上反倒一点私密都没有。”' OR id = 'df9eb910b7bb');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'f40e4a49a965', '每个人都疑心自己至少具备一种基本美德，而我的是这一种：我是我所认识的为数不多的诚实的人之一。', 'Everyone suspects himself of at least one of the cardinal virtues, and this is mine: I am one of the few honest people that I have ever known.', '菲茨杰拉德', '《了不起的盖茨比》第三章', 'book', '["诚实"]', 'public', '', 1792512014000, 1792512014000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '每个人都疑心自己至少具备一种基本美德，而我的是这一种：我是我所认识的为数不多的诚实的人之一。' OR id = 'f40e4a49a965');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'a96754eb246b', '“世上只有被追逐的人、追逐的人、忙碌的人，和疲惫的人。”', '“There are only the pursued, the pursuing, the busy, and the tired.”', '菲茨杰拉德', '《了不起的盖茨比》第四章', 'book', '["人生"]', 'public', '', 1792512013000, 1792512013000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '“世上只有被追逐的人、追逐的人、忙碌的人，和疲惫的人。”' OR id = 'a96754eb246b');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '501c4e44cd05', '也许他忽然意识到，那盏灯巨大的意义如今已永远消失了。与曾经横亘在他和黛西之间的遥远距离相比，那盏灯似乎离她很近，近得几乎触手可及，就像星星离月亮那样近。如今它又只是码头上的一盏绿灯了。他心中令人着迷的事物，又少了一件。', 'Possibly it had occurred to him that the colossal significance of that light had now vanished forever. Compared to the great distance that had separated him from Daisy it had seemed very near to her, almost touching her. It had seemed as close as a star to the moon. Now it was again a green light on a dock. His count of enchanted objects had diminished by one.', '菲茨杰拉德', '《了不起的盖茨比》第五章', 'book', '["梦想","失去"]', 'public', '', 1792512012000, 1792512012000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '也许他忽然意识到，那盏灯巨大的意义如今已永远消失了。与曾经横亘在他和黛西之间的遥远距离相比，那盏灯似乎离她很近，近得几乎触手可及，就像星星离月亮那样近。如今它又只是码头上的一盏绿灯了。他心中令人着迷的事物，又少了一件。' OR id = '501c4e44cd05');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '46ecbe0b68f6', '即使在那个下午，也一定有过某些时刻，黛西没能企及他的梦想——不是她的过错，而是因为他的幻想太过磅礴。那幻想早已超越了她，超越了一切。他以创造的激情投身其中，不断添砖加瓦，用每一根飘到他身边的鲜亮羽毛去装点它。再多的火焰与鲜活，也敌不过一个人在他幽灵般的心里所积存的东西。', 'There must have been moments even that afternoon when Daisy tumbled short of his dreams—not through her own fault, but because of the colossal vitality of his illusion. It had gone beyond her, beyond everything. He had thrown himself into it with a creative passion, adding to it all the time, decking it out with every bright feather that drifted his way. No amount of fire or freshness can challenge what a man can store up in his ghostly heart.', '菲茨杰拉德', '《了不起的盖茨比》第五章', 'book', '["梦想","幻想"]', 'public', '', 1792512011000, 1792512011000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '即使在那个下午，也一定有过某些时刻，黛西没能企及他的梦想——不是她的过错，而是因为他的幻想太过磅礴。那幻想早已超越了她，超越了一切。他以创造的激情投身其中，不断添砖加瓦，用每一根飘到他身边的鲜亮羽毛去装点它。再多的火焰与鲜活，也敌不过一个人在他幽灵般的心里所积存的东西。' OR id = '46ecbe0b68f6');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '53fa63711791', '“你没法重复过去。”“没法重复过去？”他难以置信地喊道，“当然可以！”', '“You can’t repeat the past.” “Can’t repeat the past?” he cried incredulously. “Why of course you can!”', '菲茨杰拉德', '《了不起的盖茨比》第六章', 'book', '["过去","执念"]', 'public', '', 1792512010000, 1792512010000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '“你没法重复过去。”“没法重复过去？”他难以置信地喊道，“当然可以！”' OR id = '53fa63711791');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '13c161ce5937', '事实上，长岛西卵的杰伊·盖茨比，是从他对自己的柏拉图式构想中诞生的。', 'The truth was that Jay Gatsby of West Egg, Long Island, sprang from his Platonic conception of himself.', '菲茨杰拉德', '《了不起的盖茨比》第六章', 'book', '["自我","梦想"]', 'public', '', 1792512009000, 1792512009000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '事实上，长岛西卵的杰伊·盖茨比，是从他对自己的柏拉图式构想中诞生的。' OR id = '13c161ce5937');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'f9ce7ff5f7fb', '“今天下午我们做点什么好呢？”黛西喊道，“还有明天，还有往后的三十年？”“别这么消沉，”乔丹说，“等秋天天一凉，生活就又重新开始了。”', '“What’ll we do with ourselves this afternoon?” cried Daisy, “and the day after that, and the next thirty years?” “Don’t be morbid,” Jordan said. “Life starts all over again when it gets crisp in the fall.”', '菲茨杰拉德', '《了不起的盖茨比》第七章', 'book', '["季节","重新开始"]', 'public', '', 1792512008000, 1792512008000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '“今天下午我们做点什么好呢？”黛西喊道，“还有明天，还有往后的三十年？”“别这么消沉，”乔丹说，“等秋天天一凉，生活就又重新开始了。”' OR id = 'f9ce7ff5f7fb');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '5f3fcf213cd6', '“她的声音里满是金钱。”他突然说。正是如此。我以前从没明白过。那声音里满是金钱——这正是其中起伏不息的无穷魅力，是它叮当的回响，是它铙钹般的歌声……高高的白色宫殿里，国王的女儿，那个黄金女孩……', '“Her voice is full of money,” he said suddenly. That was it. I’d never understood before. It was full of money—that was the inexhaustible charm that rose and fell in it, the jingle of it, the cymbals’ song of it … High in a white palace the king’s daughter, the golden girl …', '菲茨杰拉德', '《了不起的盖茨比》第七章', 'book', '["金钱","欲望"]', 'public', '', 1792512007000, 1792512007000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '“她的声音里满是金钱。”他突然说。正是如此。我以前从没明白过。那声音里满是金钱——这正是其中起伏不息的无穷魅力，是它叮当的回响，是它铙钹般的歌声……高高的白色宫殿里，国王的女儿，那个黄金女孩……' OR id = '5f3fcf213cd6');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '872cb3abbd36', '三十岁——预示着十年的孤独：可以结交的单身朋友越来越少，满怀的热情越来越薄，头发也越来越稀。', 'Thirty—the promise of a decade of loneliness, a thinning list of single men to know, a thinning briefcase of enthusiasm, thinning hair.', '菲茨杰拉德', '《了不起的盖茨比》第七章', 'book', '["时间","孤独"]', 'public', '', 1792512006000, 1792512006000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '三十岁——预示着十年的孤独：可以结交的单身朋友越来越少，满怀的热情越来越薄，头发也越来越稀。' OR id = '872cb3abbd36');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '567069bc4f9d', '他们是粗心大意的人，汤姆和黛西——他们砸碎了东西、毁掉了生灵，然后便退回到他们的金钱里，退回到他们无边的漫不经心里，或者退回到别的什么把他们维系在一起的东西里，留下别人去收拾他们弄出的烂摊子……', 'They were careless people, Tom and Daisy—they smashed up things and creatures and then retreated back into their money or their vast carelessness, or whatever it was that kept them together, and let other people clean up the mess they had made …', '菲茨杰拉德', '《了不起的盖茨比》第九章', 'book', '["人性","金钱"]', 'public', '', 1792512005000, 1792512005000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '他们是粗心大意的人，汤姆和黛西——他们砸碎了东西、毁掉了生灵，然后便退回到他们的金钱里，退回到他们无边的漫不经心里，或者退回到别的什么把他们维系在一起的东西里，留下别人去收拾他们弄出的烂摊子……' OR id = '567069bc4f9d');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '806d5737e2c8', '“让我们学会在一个人活着的时候向他表达友谊，而不是等到他死了以后。”', '“Let us learn to show our friendship for a man when he is alive and not after he is dead.”', '菲茨杰拉德', '《了不起的盖茨比》第九章', 'book', '["友谊"]', 'public', '', 1792512004000, 1792512004000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '“让我们学会在一个人活着的时候向他表达友谊，而不是等到他死了以后。”' OR id = '806d5737e2c8');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'ed4c58146684', '“我三十岁了，”我说，“对自己撒谎、还把它叫作荣誉——这样的年纪，我已经过了五年。”', '“I’m thirty,” I said. “I’m five years too old to lie to myself and call it honour.”', '菲茨杰拉德', '《了不起的盖茨比》第九章', 'book', '["诚实","成长"]', 'public', '', 1792512003000, 1792512003000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '“我三十岁了，”我说，“对自己撒谎、还把它叫作荣誉——这样的年纪，我已经过了五年。”' OR id = 'ed4c58146684');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT '3e47501002eb', '盖茨比相信那盏绿灯，相信那个一年年在我们面前退远的、令人狂喜的未来。那时它从我们手边溜走了，可那没关系——明天我们会跑得更快，把手臂伸得更远……总有一个晴朗的早晨——', 'Gatsby believed in the green light, the orgastic future that year by year recedes before us. It eluded us then, but that’s no matter—tomorrow we will run faster, stretch out our arms further … And one fine morning—', '菲茨杰拉德', '《了不起的盖茨比》第九章', 'book', '["梦想","未来"]', 'public', '', 1792512002000, 1792512002000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '盖茨比相信那盏绿灯，相信那个一年年在我们面前退远的、令人狂喜的未来。那时它从我们手边溜走了，可那没关系——明天我们会跑得更快，把手臂伸得更远……总有一个晴朗的早晨——' OR id = '3e47501002eb');
INSERT INTO quotes (id, text, trans, author, source, source_type, tags, visibility, note, created_at, updated_at) SELECT 'd84f66716b84', '于是我们奋力向前，如逆流而上的小舟，不停地被浪潮推回到过去。', 'So we beat on, boats against the current, borne back ceaselessly into the past.', '菲茨杰拉德', '《了不起的盖茨比》第九章', 'book', '["时间","过去"]', 'public', '', 1792512001000, 1792512001000 WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE text = '于是我们奋力向前，如逆流而上的小舟，不停地被浪潮推回到过去。' OR id = 'd84f66716b84');

INSERT INTO collections (id, name, intro, created_at, sort) SELECT '9148a364715e', '尼采', '尼采原著摘句，英文为公版译本', 1792512000000, (SELECT COALESCE(MAX(sort), -1) + 1 FROM collections) WHERE NOT EXISTS (SELECT 1 FROM collections WHERE name = '尼采' OR id = '9148a364715e');
INSERT INTO collections (id, name, intro, created_at, sort) SELECT 'ead080a23114', '了不起的盖茨比', '菲茨杰拉德原文摘句', 1792512001000, (SELECT COALESCE(MAX(sort), -1) + 1 FROM collections) WHERE NOT EXISTS (SELECT 1 FROM collections WHERE name = '了不起的盖茨比' OR id = 'ead080a23114');

INSERT OR IGNORE INTO collection_quotes (collection_id, quote_id, position) SELECT (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1), (SELECT id FROM quotes WHERE text = '我向你们教授超人。人是一种应当被超越的东西。为了超越人，你们做过什么？' ORDER BY created_at, id LIMIT 1), (SELECT COALESCE(MAX(position), -1) + 1 FROM collection_quotes WHERE collection_id = (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1)) WHERE (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1) IS NOT NULL AND (SELECT id FROM quotes WHERE text = '我向你们教授超人。人是一种应当被超越的东西。为了超越人，你们做过什么？' ORDER BY created_at, id LIMIT 1) IS NOT NULL;
INSERT OR IGNORE INTO collection_quotes (collection_id, quote_id, position) SELECT (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1), (SELECT id FROM quotes WHERE text = '人是一根绳索，系在野兽与超人之间——一根悬在深渊之上的绳索。人之伟大，在于他是一座桥梁，而不是终点。' ORDER BY created_at, id LIMIT 1), (SELECT COALESCE(MAX(position), -1) + 1 FROM collection_quotes WHERE collection_id = (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1)) WHERE (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1) IS NOT NULL AND (SELECT id FROM quotes WHERE text = '人是一根绳索，系在野兽与超人之间——一根悬在深渊之上的绳索。人之伟大，在于他是一座桥梁，而不是终点。' ORDER BY created_at, id LIMIT 1) IS NOT NULL;
INSERT OR IGNORE INTO collection_quotes (collection_id, quote_id, position) SELECT (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1), (SELECT id FROM quotes WHERE text = '我告诉你们：人的心中必须还留有混沌，才能孕育出一颗舞动的星辰。' ORDER BY created_at, id LIMIT 1), (SELECT COALESCE(MAX(position), -1) + 1 FROM collection_quotes WHERE collection_id = (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1)) WHERE (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1) IS NOT NULL AND (SELECT id FROM quotes WHERE text = '我告诉你们：人的心中必须还留有混沌，才能孕育出一颗舞动的星辰。' ORDER BY created_at, id LIMIT 1) IS NOT NULL;
INSERT OR IGNORE INTO collection_quotes (collection_id, quote_id, position) SELECT (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1), (SELECT id FROM quotes WHERE text = '一切文字之中，我只爱那用血写成的。用血去写吧，你会懂得：血就是精神。' ORDER BY created_at, id LIMIT 1), (SELECT COALESCE(MAX(position), -1) + 1 FROM collection_quotes WHERE collection_id = (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1)) WHERE (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1) IS NOT NULL AND (SELECT id FROM quotes WHERE text = '一切文字之中，我只爱那用血写成的。用血去写吧，你会懂得：血就是精神。' ORDER BY created_at, id LIMIT 1) IS NOT NULL;
INSERT OR IGNORE INTO collection_quotes (collection_id, quote_id, position) SELECT (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1), (SELECT id FROM quotes WHERE text = '我们热爱生命，不是因为习惯了活着，而是因为习惯了爱。爱里总有几分疯狂；而疯狂里，也总有几分章法。' ORDER BY created_at, id LIMIT 1), (SELECT COALESCE(MAX(position), -1) + 1 FROM collection_quotes WHERE collection_id = (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1)) WHERE (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1) IS NOT NULL AND (SELECT id FROM quotes WHERE text = '我们热爱生命，不是因为习惯了活着，而是因为习惯了爱。爱里总有几分疯狂；而疯狂里，也总有几分章法。' ORDER BY created_at, id LIMIT 1) IS NOT NULL;
INSERT OR IGNORE INTO collection_quotes (collection_id, quote_id, position) SELECT (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1), (SELECT id FROM quotes WHERE text = '我只会相信一位懂得跳舞的神。' ORDER BY created_at, id LIMIT 1), (SELECT COALESCE(MAX(position), -1) + 1 FROM collection_quotes WHERE collection_id = (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1)) WHERE (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1) IS NOT NULL AND (SELECT id FROM quotes WHERE text = '我只会相信一位懂得跳舞的神。' ORDER BY created_at, id LIMIT 1) IS NOT NULL;
INSERT OR IGNORE INTO collection_quotes (collection_id, quote_id, position) SELECT (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1), (SELECT id FROM quotes WHERE text = '攀上最高峰的人，会笑看一切悲剧——无论是戏台上的，还是现实里的。' ORDER BY created_at, id LIMIT 1), (SELECT COALESCE(MAX(position), -1) + 1 FROM collection_quotes WHERE collection_id = (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1)) WHERE (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1) IS NOT NULL AND (SELECT id FROM quotes WHERE text = '攀上最高峰的人，会笑看一切悲剧——无论是戏台上的，还是现实里的。' ORDER BY created_at, id LIMIT 1) IS NOT NULL;
INSERT OR IGNORE INTO collection_quotes (collection_id, quote_id, position) SELECT (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1), (SELECT id FROM quotes WHERE text = '你的身体里，藏着比你最高明的智慧更多的明智。' ORDER BY created_at, id LIMIT 1), (SELECT COALESCE(MAX(position), -1) + 1 FROM collection_quotes WHERE collection_id = (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1)) WHERE (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1) IS NOT NULL AND (SELECT id FROM quotes WHERE text = '你的身体里，藏着比你最高明的智慧更多的明智。' ORDER BY created_at, id LIMIT 1) IS NOT NULL;
INSERT OR IGNORE INTO collection_quotes (collection_id, quote_id, position) SELECT (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1), (SELECT id FROM quotes WHERE text = '人和树是一样的。越是想向高处、向光明生长，他的根就越是用力地扎向大地，扎向下方，扎进黑暗与深处——扎进恶。' ORDER BY created_at, id LIMIT 1), (SELECT COALESCE(MAX(position), -1) + 1 FROM collection_quotes WHERE collection_id = (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1)) WHERE (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1) IS NOT NULL AND (SELECT id FROM quotes WHERE text = '人和树是一样的。越是想向高处、向光明生长，他的根就越是用力地扎向大地，扎向下方，扎进黑暗与深处——扎进恶。' ORDER BY created_at, id LIMIT 1) IS NOT NULL;
INSERT OR IGNORE INTO collection_quotes (collection_id, quote_id, position) SELECT (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1), (SELECT id FROM quotes WHERE text = '逃吧，我的朋友，逃进你的孤独里去！我看见你被大人物的喧嚣震聋了耳朵，又被小人物的毒刺蜇得遍体是伤。' ORDER BY created_at, id LIMIT 1), (SELECT COALESCE(MAX(position), -1) + 1 FROM collection_quotes WHERE collection_id = (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1)) WHERE (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1) IS NOT NULL AND (SELECT id FROM quotes WHERE text = '逃吧，我的朋友，逃进你的孤独里去！我看见你被大人物的喧嚣震聋了耳朵，又被小人物的毒刺蜇得遍体是伤。' ORDER BY created_at, id LIMIT 1) IS NOT NULL;
INSERT OR IGNORE INTO collection_quotes (collection_id, quote_id, position) SELECT (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1), (SELECT id FROM quotes WHERE text = '一切伟大的事物，都发生在远离市场、远离名声的地方。' ORDER BY created_at, id LIMIT 1), (SELECT COALESCE(MAX(position), -1) + 1 FROM collection_quotes WHERE collection_id = (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1)) WHERE (SELECT id FROM collections WHERE name = '尼采' ORDER BY created_at, id LIMIT 1) IS NOT NULL AND (SELECT id FROM quotes WHERE text = '一切伟大的事物，都发生在远离市场、远离名声的地方。' ORDER BY created_at, id LIMIT 1) IS NOT NULL;
