INSERT OR IGNORE INTO collection_quotes (collection_id, quote_id, position) SELECT (SELECT id FROM collections WHERE name = '了不起的盖茨比' ORDER BY created_at, id LIMIT 1), (SELECT id FROM quotes WHERE text = '“让我们学会在一个人活着的时候向他表达友谊，而不是等到他死了以后。”' ORDER BY created_at, id LIMIT 1), (SELECT COALESCE(MAX(position), -1) + 1 FROM collection_quotes WHERE collection_id = (SELECT id FROM collections WHERE name = '了不起的盖茨比' ORDER BY created_at, id LIMIT 1)) WHERE (SELECT id FROM collections WHERE name = '了不起的盖茨比' ORDER BY created_at, id LIMIT 1) IS NOT NULL AND (SELECT id FROM quotes WHERE text = '“让我们学会在一个人活着的时候向他表达友谊，而不是等到他死了以后。”' ORDER BY created_at, id LIMIT 1) IS NOT NULL;
