INSERT OR IGNORE INTO collection_quotes (collection_id, quote_id, position) SELECT (SELECT id FROM collections WHERE name = '了不起的盖茨比' ORDER BY created_at, id LIMIT 1), (SELECT id FROM quotes WHERE text = '盖茨比相信那盏绿灯，相信那个一年年在我们面前退远的、令人狂喜的未来。那时它从我们手边溜走了，可那没关系——明天我们会跑得更快，把手臂伸得更远……总有一个晴朗的早晨——' ORDER BY created_at, id LIMIT 1), (SELECT COALESCE(MAX(position), -1) + 1 FROM collection_quotes WHERE collection_id = (SELECT id FROM collections WHERE name = '了不起的盖茨比' ORDER BY created_at, id LIMIT 1)) WHERE (SELECT id FROM collections WHERE name = '了不起的盖茨比' ORDER BY created_at, id LIMIT 1) IS NOT NULL AND (SELECT id FROM quotes WHERE text = '盖茨比相信那盏绿灯，相信那个一年年在我们面前退远的、令人狂喜的未来。那时它从我们手边溜走了，可那没关系——明天我们会跑得更快，把手臂伸得更远……总有一个晴朗的早晨——' ORDER BY created_at, id LIMIT 1) IS NOT NULL;
INSERT OR IGNORE INTO collection_quotes (collection_id, quote_id, position) SELECT (SELECT id FROM collections WHERE name = '了不起的盖茨比' ORDER BY created_at, id LIMIT 1), (SELECT id FROM quotes WHERE text = '于是我们奋力向前，如逆流而上的小舟，不停地被浪潮推回到过去。' ORDER BY created_at, id LIMIT 1), (SELECT COALESCE(MAX(position), -1) + 1 FROM collection_quotes WHERE collection_id = (SELECT id FROM collections WHERE name = '了不起的盖茨比' ORDER BY created_at, id LIMIT 1)) WHERE (SELECT id FROM collections WHERE name = '了不起的盖茨比' ORDER BY created_at, id LIMIT 1) IS NOT NULL AND (SELECT id FROM quotes WHERE text = '于是我们奋力向前，如逆流而上的小舟，不停地被浪潮推回到过去。' ORDER BY created_at, id LIMIT 1) IS NOT NULL;
